<?php
declare(strict_types=1);
namespace Bridge;

use Security, FileUpload, Logger, Database, Bridge\Mailer, E2EEncrypt;

class Controller {
    private array $result = [];
    private int $uid = 0; private string $ip = '0'; private string $mode = ''; private string $act = '';
    private bool $isPoll = false;

    private const ROUTES = [
'board_register'=>'authRegister','board_login'=>'authLogin','board_logout'=>'authLogout','all_logout'=>'authAllLogout',
