'totp_delete'=>'totpDelete','totp_delete_user'=>'totpDeleteUser','totp_cancel'=>'totpCancel',
'leave_post'=>'productCreate','revise_post'=>'productUpdate','admin_delete_prd'=>'adminDeleteProduct',
'account_settings'=>'accountSettings','account_delete_self'=>'accountDeleteSelf',
'chat_send'=>'chatSend','chat_media'=>'chatMedia','chat_priv'=>'chatPriv','report'=>'reportCreate',
'wallet_charge'=>'walletCharge','wallet_transfer'=>'walletTransfer','wallet_buy'=>'walletBuy',
'transfer_confirm'=>'transferConfirm','media_delete'=>'mediaDelete','media_set_main'=>'mediaSetMain',
'payment_info'=>'paymentInfo','check_dup_email'=>'checkDupEmail','check_dup_id'=>'checkDupId',
