'admin_toggle_admin'=>'adminToggleAdmin','admin_edit_terms'=>'adminEditTerms','admin_edit_privacy'=>'adminEditPrivacy','admin_delete_room'=>'adminDeleteRoom','admin_toggle_room_block'=>'adminToggleRoomBlock',
'firewall_add'=>'firewallAdd','firewall_del'=>'firewallDel','notice_set'=>'noticeSet',
'service_maint'=>'serviceMaintenance','notice_delete'=>'noticeDelete','notice_popup_toggle'=>'noticePopupToggle',
