    public function dispatch(): self {
        global $sql, $system_v; $this->act = $_GET['act'] ?? ''; $this->isPoll = ($this->act === 'chat_poll');
        $this->ip = client_ip(); $this->uid = (int)($system_v['login']['number'] ?? 0);
        if (stripos($_SERVER['CONTENT_TYPE'] ?? '', 'application/json') === 0) { $raw = file_get_contents('php://input'); if ($raw !== '' && $raw !== false && is_array($d = json_decode($raw, true))) $_POST = array_merge($_POST, $d); }
        // ECDH: 클라이언트 공개키로 AES 키 도출 (매 요청마다 갱신 가능)
        if (!empty($_POST['_dh_pub'])) { E2EEncrypt::deriveKey($_POST['_dh_pub']); }
        if (!empty($_POST['_enc_data']) && !empty($_SESSION['e2ekey'])) { $dec = E2EEncrypt::decrypt($_POST['_enc_data'], $_POST['_enc_iv']??'', $_POST['_enc_tag']??''); if ($dec !== '') { $parsed = json_decode($dec, true); if (is_array($parsed)) $_POST = array_merge($_POST, $parsed); } }
        if ($this->isPoll) { if (!Security::csrf_ok()) json_out(['error' => 1, 'description' => 'CSRF 인증 실패']); }
        else Security::csrf_guard();
        if ($this->firewallBlocked($this->ip)) { http_response_code(403); json_out(['error' => 1, 'description' => '접근이 차단되었습니다']); }
        $m = (string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key=?","s",["maintenance"]);
        if ($m==='1'&&(int)($system_v['login']['group']??0)!==1&&!$this->isPoll){$cm=$_POST['mode']??($_GET['mode']??'');if(!in_array($cm,['board_logout','all_logout','board_login','board_register','admin_auth','totp_cancel','master_admin_create','page_load'],true)){unset($_SESSION['login']);json_out(['error'=>1,'description'=>'서비스 점검 중입니다','redirect'=>'/?mode=authorize','notice'=>1]);}}
        if ($this->isPoll) return $this->chatPoll();
        $this->mode = $_POST['mode'] ?? ($_GET['mode'] ?? ''); if (!isset(self::ROUTES[$this->mode])) { json_out(['error' => 1, 'description' => '올바르지 않은 요청']); }
        $this->gate(); $m = self::ROUTES[$this->mode]; $this->$m(); return $this; }

    public function respond(): void {
        $r = !empty($this->result) ? $this->result : ['error' => 1, 'description' => '처리되지 않음'];
        $r['__new_csrf'] = stable_csrf();
        $plain = json_encode($r, JSON_UNESCAPED_UNICODE);
        if (!empty($_SESSION['e2ekey'])) { $enc = E2EEncrypt::encrypt($plain); if ($enc !== $plain) { header('Content-Type: application/json; charset=utf-8'); echo $enc; exit; } }
        json_out($r);
    }
    private function ok(string $d, array $e = []): void { Logger::request($this->mode, 1, $d, $this->uid ?: null, $this->ip); if($this->uid&&(int)($_SESSION['login']['group']??0)===1)Logger::admin($this->uid,$this->mode,null,$d); $this->result = array_merge(['success' => 1, 'description' => $d], $e); }
    private function fail(string $d, array $e = []): void { Logger::request($this->mode, 0, $d, $this->uid ?: null, $this->ip); $this->result = array_merge(['error' => 1, 'description' => $d], $e); }

    private function gate(): void { global $system_v;
        $nl = ['board_login','board_register','check_dup_email','check_dup_id','totp_cancel','master_admin_create','pw_reset','admin_auth','page_load'];
        if (!in_array($this->mode, $nl) && (int)$system_v['login']['valid'] !== 1) json_out(['error' => 1, 'description' => '로그인이 필요합니다']);
        if (in_array($this->mode, ['board_login','board_register']) && (int)$system_v['login']['valid'] === 1) json_out(['error' => 1, 'description' => '이미 로그인 되어 있습니다']);
        $db = in_array($this->mode, ['leave_post','revise_post','wallet_transfer','wallet_buy','report','chat_send','chat_media','chat_priv']);
        if ($db && !empty($system_v['login']['dormant'])) json_out(['error' => 1, 'description' => '휴면 계정입니다']);
        $ao = in_array($this->mode, ['admin_report_act','admin_blind_prd','admin_dormant_user','admin_toggle_reportban','admin_toggle_admin','admin_edit_terms','admin_edit_privacy','admin_delete_prd','admin_delete_room','admin_toggle_room_block','firewall_add','firewall_del','notice_set','service_maint','admin_delete_user','admin_deactivate_user','admin_autopromote','tor_toggle','ua_toggle','ua_save','log_cleanup','totp_delete_user','admin_revoke_admin','notice_delete','notice_popup_toggle']);
        if ($ao && (int)($system_v['login']['group']??0) !== 1) json_out(['error' => 1, 'description' => '관리자 권한이 필요합니다']);
        if (in_array($this->mode, ['totp_delete_user','admin_revoke_admin','admin_delete_user','notice_delete']) && !$this->isMasterAdmin()) json_out(['error' => 1, 'description' => '마스터 관리자만 가능합니다']);
        if ($ao && (empty($_SESSION['admin_verified']) || (time() - (int)$_SESSION['admin_verified']) > 60)) json_out(['error' => 1, 'description' => '관리자 인증이 필요합니다', 'need_admin_auth' => 1]); }

    private function isMasterAdmin(): bool { global $sql; return (int)$sql->scalar("SELECT acc_group FROM users WHERE acc_number=?", 'i', [$this->uid]) === 1; }
    private function isLocalIp(string $ip): bool { if ($ip==='127.0.0.1'||$ip==='::1') return true; if (strpos($ip,'192.168.')===0||strpos($ip,'10.')===0) return true; if (strpos($ip,'172.')===0) {$s=(int)explode('.',$ip)[1];return $s>=16&&$s<=31;} return false; }

    private function firewallBlocked(string $ip): bool { global $sql; if ($ip==='0'||$ip==='') return false;
        $ua=$_SERVER['HTTP_USER_AGENT']??'';$cc=ip_to_cc($ip);$torOn=((string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key='tor'")?:'0')==='1';if($torOn){$torIps=include __DIR__.'/../tor_ip.php';if(is_array($torIps)&&in_array($ip,$torIps,true))return true;}
        $uaOn=((string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key='ua_block'")?:'0')==='1';if($uaOn&&$ua!==''){$uaList=(string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key='ua_list'");$uaMode=(string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key='ua_mode'");$patterns=array_values(array_filter(array_map('trim',explode("\n",$uaList)),function($p){return$p!=='';}));if(count($patterns)>0){if($uaMode==='and'){$hit=true;foreach($patterns as $p){if(stripos($ua,$p)===false){$hit=false;break;}}if($hit)return true;}else{foreach($patterns as $p){if(stripos($ua,$p)!==false)return true;}}}}
        $rows=$sql->run("SELECT fw_type,fw_rule,fw_pattern FROM ip_firewall WHERE fw_rule<>'ua'");if(!$rows)return false;
        $we=false;$wo=false;foreach($rows as $r){$m=$this->fwMatch($r['fw_rule'],$r['fw_pattern'],$ip,$cc,$ua);if((int)$r['fw_type']===1){$we=true;if($m)$wo=true;}elseif($m)return true;}return $we&&!$wo;}
    private function fwMatch(string $r,string $p,string $ip,string $cc,string $ua): bool { return match($r){'ip'=>hash_equals($p,$ip),'wildcard'=>fnmatch($p,$ip),'country'=>$cc!==''&&$p===$cc,'tor'=>in_array($ip,array_map('trim',explode(',',$p)),true),'ua'=>$p!==''&&stripos($ua,$p)!==false,default=>false}; }
    
    private function torToggle(): void { global $sql; $cur=(string)($sql->scalar("SELECT ss_value FROM system_status WHERE ss_key='tor'")?:'0');$n=$cur==='1'?'0':'1';$sql->run("DELETE FROM system_status WHERE ss_key='tor'");$sql->run("INSERT INTO system_status (ss_key,ss_value,ss_time) VALUES ('tor',?,NOW())",'s',[$n]);$this->ok($n==='1'?'TOR 차단 활성화':'TOR 차단 비활성화'); }private function firewallAdd(): void { global $sql; $fp=trim($_POST['fw_pattern']??'');if($fp===''||strlen($fp)>120){$this->fail('패턴 오류');return;}$sql->run("INSERT INTO ip_firewall (fw_type,fw_rule,fw_pattern,fw_memo,fw_time) VALUES (?,?,?,?,NOW())",'isss',[(int)(only_digits($_POST['fw_type']??'0',1)),$_POST['fw_rule']??'ip',$fp,mb_substr($_POST['fw_memo']??'',0,200)]);$this->ok('추가되었습니다');}
    private function firewallDel(): void { global $sql; $id=only_digits($_POST['fw_id']??'',20);if($id===''){$this->fail('ID 오류');return;}$sql->run("DELETE FROM ip_firewall WHERE fw_id=?",'i',[(int)$id]);$this->ok('삭제되었습니다');}

    private function authRegister(): void { global $sql; $id=trim($_POST['form_id']??'');$nick=trim($_POST['form_nick']??'');if($nick===''||mb_strlen($nick)>20)$nick='User';$pw=trim($_POST['form_pw']??'');$email=trim($_POST['form_email']??'');$msgs=[];
        if(!valid_accid($id))$msgs[]='ID: 영문/숫자 4~20자리'; if(!valid_password($pw))$msgs[]='비밀번호: 8~32자리';
        if(trim($_POST['form_pw_re']??'')!==$pw)$msgs[]='비밀번호 재입력 불일치'; if(!valid_email($email))$msgs[]='허용되지 않은 이메일 도메인';
        if(($_POST['form_check_terms']??'')!=='on')$msgs[]='약관 동의 필요'; if($msgs){$this->fail(implode(' / ',$msgs));return;}
        if($sql->one("SELECT 1 FROM users WHERE acc_id=?",'s',[$id])){$this->fail('이미 존재하는 ID입니다');return;}
        if($sql->one("SELECT 1 FROM users WHERE acc_email=?",'s',[$email])){$this->fail('이미 등록된 이메일입니다');return;}
        $sql->run("INSERT INTO users (acc_id,acc_nick,acc_pw,acc_email,acc_group,acc_status,acc_onelogin,registertime) VALUES (?,?,?,?,0,0,1,?)",'sssss',[$id,$nick,hash_password($pw),$email,now()]);
        $this->ok('정상적으로 회원가입 되었습니다',['redirect'=>'/?mode=authorize','notice'=>1]);}
    private function checkDupId(): void { global $sql; $id=trim($_POST['form_id']??'');if(!valid_accid($id)){$this->fail('ID 형식 오류');return;}if($sql->one("SELECT 1 FROM users WHERE acc_id=?",'s',[$id])){$this->fail('이미 사용 중인 ID');return;}$this->ok('사용 가능한 ID입니다');}
    private function checkDupEmail(): void { global $sql; $email=trim($_POST['form_email']??'');if(!valid_email($email)){$this->fail('이메일 형식 오류');return;}if($sql->one("SELECT 1 FROM users WHERE acc_email=?",'s',[$email])){$this->fail('이미 사용 중인 이메일');return;}$this->ok('사용 가능한 이메일입니다');}

    private function authLogin(): void { global $sql; $id=trim($_POST['form_id']??'');$pw=trim($_POST['form_pw']??'');$totp=trim($_POST['form_totp']??'');
        if(!empty($_SESSION['totp_pending'])){$pid=(int)$_SESSION['totp_pending'];if(!preg_match('/^[0-9]{6}$/',$totp)){$this->fail('TOTP 코드 6자리를 입력하세요');return;}$u=$sql->one("SELECT acc_totp_secret FROM users WHERE acc_number=?",'i',[$pid]);if(!$u||!Security::totp_verify($u['acc_totp_secret'],$totp)){$this->fail('TOTP 코드가 올바르지 않습니다');return;}unset($_SESSION['totp_pending'],$_SESSION['totp_pending_id']);$this->doLogin($pid);$this->ok('로그인 되었습니다',['redirect'=>'/']);return;}
        if($id===''||!valid_password($pw)){$this->fail('아이디 또는 비밀번호가 올바르지 않습니다');return;}$hpw=hash_password($pw);
        $u=$sql->one("SELECT acc_number,acc_id,acc_onelogin,acc_group,acc_status,acc_totp_ok FROM users WHERE acc_id=? AND acc_pw=?",'ss',[$id,$hpw]);if(!$u){Logger::login(null,$this->ip,ip_to_cc($this->ip),$_SERVER['HTTP_USER_AGENT']??'',0);$this->fail('아이디 또는 비밀번호가 올바르지 않습니다');return;}$st=(int)$u['acc_status'];if($st===2){$this->fail('휴면 계정입니다');return;}if($st===3){$this->fail('정지된 계정입니다');return;}if((int)$u['acc_totp_ok']===1){$_SESSION['totp_pending']=(int)$u['acc_number'];$_SESSION['totp_pending_id']=$id;$this->fail('TOTP 코드를 입력하세요',['totp_need'=>1]);return;}$this->doLogin((int)$u['acc_number']);$this->ok('로그인 되었습니다',['redirect'=>'/']);}
    private function doLogin(int $an): void { global $sql; $cc=ip_to_cc($this->ip); $ol=(int)$sql->scalar("SELECT acc_onelogin FROM users WHERE acc_number=?",'i',[$an]);$sql->run("UPDATE users SET acc_login_ip=?,acc_login_cc=?,lastlogin=NOW() WHERE acc_number=?",'ssi',[$this->ip,$cc,$an]);$_SESSION['login']=['number'=>$an,'valid'=>1,'onelogin'=>$ol,'group'=>(int)$sql->scalar("SELECT acc_group FROM users WHERE acc_number=?",'i',[$an])];unset($_SESSION['admin_verified']);$_SESSION['user_ip']=$this->ip;session_regenerate_id(true);Logger::login($an,$this->ip,$cc,$_SERVER['HTTP_USER_AGENT']??'',1);rotate_csrf();}
    private function totpCancel(): void { unset($_SESSION['totp_pending'],$_SESSION['totp_pending_id'],$_SESSION['pending_totp_secret']);$this->ok('취소되었습니다');}
    private function authLogout(): void { unset($_SESSION['login']);if(session_status()===PHP_SESSION_ACTIVE){session_destroy();session_start();}rotate_csrf();$this->ok('로그아웃 되었습니다',['redirect'=>'/','notice'=>1]);}
    private function authAllLogout(): void { global $sql; $c=(int)$sql->scalar("SELECT acc_onelogin FROM users WHERE acc_number=?",'i',[$this->uid]);$sql->run("UPDATE users SET acc_onelogin=? WHERE acc_number=?",'ii',[$c+1,$this->uid]);unset($_SESSION['login']);if(session_status()===PHP_SESSION_ACTIVE){session_destroy();session_start();}rotate_csrf();$this->ok('모든 기기에서 로그아웃 되었습니다',['redirect'=>'/','notice'=>1]);}

    private function emailVerify(): void { global $sql; $code=trim($_POST['code']??'');if(!preg_match('/^[0-9]{6}$/',$code)){$this->fail('6자리 코드를 입력하세요');return;}$r=$sql->one("SELECT ev_id,ev_code,ev_expire FROM email_verify WHERE ev_user=? ORDER BY ev_id DESC LIMIT 1",'i',[$this->uid]);if(!$r){$this->fail('인증 요청이 없습니다');return;}if(strtotime($r['ev_expire'])<time()){$this->fail('인증코드가 만료되었습니다');return;}if(!hash_equals($r['ev_code'],$code)){$this->fail('인증코드가 일치하지 않습니다');return;}$sql->run("UPDATE users SET acc_status=0 WHERE acc_number=?",'i',[$this->uid]);$sql->run("DELETE FROM email_verify WHERE ev_user=?",'i',[$this->uid]);$this->ok('이메일 인증 완료',['redirect'=>'/','notice'=>1]);}
    private function emailResend(): void { global $sql; $sql->run("DELETE FROM email_verify WHERE ev_user=?",'i',[$this->uid]);$code=mk_verify_code();$sql->run("INSERT INTO email_verify (ev_user,ev_code,ev_expire) VALUES (?,?,?)",'iss',[$this->uid,$code,date('Y-m-d H:i:s',time()+600)]);$em=(string)$sql->scalar("SELECT acc_email FROM users WHERE acc_number=?",'i',[$this->uid]);$s=Mailer::send($em,'이메일 인증코드',"코드: {$code}\n(10분 유효)",$this->uid);$this->ok('인증코드 재발송 완료',['verify_code_dev'=>$code,'mail_fail'=>!$s]);}

    private function totpInit(): void { global $sql; $ex=$sql->one("SELECT acc_totp_secret FROM users WHERE acc_number=?",'i',[$this->uid]); if($ex['acc_totp_secret']!==''){$this->fail('TOTP가 이미 설정되어 있습니다. 먼저 삭제 후 재설정하세요.');return;}$sec=Security::totp_secret();$_SESSION['pending_totp_secret']=$sec; $acc=(string)$sql->scalar("SELECT acc_id FROM users WHERE acc_number=?",'i',[$this->uid]);$iss=rawurlencode('namu');$oa="otpauth://totp/{$iss}:".rawurlencode($acc)."?secret={$sec}&issuer={$iss}&digits=6&period=30";$this->ok('TOTP 시크릿이 발급되었습니다. QR을 스캔 후 6자리 코드로 인증하면 계정에 반영됩니다.',['otpauth'=>$oa,'secret'=>$sec,'show_totp_setup'=>1]);}
    private function totpVerify(): void { global $sql; $code=trim($_POST['code']??'');if(!preg_match('/^[0-9]{6}$/',$code)){$this->fail('6자리 코드를 입력하세요');return;}$pending=$_SESSION['pending_totp_secret']??'';if($pending!==''){if(!Security::totp_verify($pending,$code)){$this->fail('TOTP 코드가 올바르지 않습니다');return;}$sql->run("UPDATE users SET acc_totp_secret=?,acc_totp_ok=1 WHERE acc_number=?",'si',[$pending,$this->uid]);unset($_SESSION['pending_totp_secret']);$this->ok('TOTP 활성화 완료');return;}$cur=(string)$sql->scalar("SELECT acc_totp_secret FROM users WHERE acc_number=?",'i',[$this->uid]);if($cur===''){$this->fail('먼저 TOTP 설정 시작을 눌러주세요.');return;}if(!Security::totp_verify($cur,$code)){$this->fail('TOTP 코드가 올바르지 않습니다');return;}$this->ok('TOTP 활성화 완료');}
    private function totpDelete(): void { global $sql; $code=trim($_POST['code']??'');if(!preg_match('/^[0-9]{6}$/',$code)){$this->fail('TOTP 코드를 입력하세요');return;}$sec=(string)$sql->scalar("SELECT acc_totp_secret FROM users WHERE acc_number=?",'i',[$this->uid]);if($sec===''||!Security::totp_verify($sec,$code)){$this->fail('TOTP 코드가 올바르지 않습니다');return;}$sql->run("UPDATE users SET acc_totp_ok=0,acc_totp_secret='' WHERE acc_number=?",'i',[$this->uid]);$this->ok('TOTP 삭제 완료');}
    private function totpDeleteUser(): void { global $sql; $u=only_digits($_POST['user']??'',20);if($u===''){$this->fail('사용자 오류');return;}$tn=(string)$sql->scalar("SELECT acc_id FROM users WHERE acc_number=?",'i',[(int)$u]);$sql->run("UPDATE users SET acc_totp_ok=0,acc_totp_secret='' WHERE acc_number=?",'i',[(int)$u]);$this->ok('사용자 TOTP 삭제 완료');}

    private function adminAuth(): void { global $sql; $u=$sql->one("SELECT acc_totp_ok,acc_totp_secret FROM users WHERE acc_number=?",'i',[$this->uid]);if(!$u||(int)$u['acc_totp_ok']!==1){$this->fail('TOTP가 설정되지 않았습니다. 마이페이지에서 먼저 TOTP를 설정하세요.');return;}$code=trim($_POST['code']??'');if(!preg_match('/^[0-9]{6}$/',$code)||!Security::totp_verify($u['acc_totp_secret'],$code)){$this->fail('TOTP 코드가 올바르지 않습니다');return;}$_SESSION['admin_verified']=time();$this->ok('관리자 인증 완료');}
    private function adminEmailVerifySend(): void { global $sql; $em=(string)$sql->scalar("SELECT acc_email FROM users WHERE acc_number=?",'i',[$this->uid]);$code=mk_verify_code();$sql->run("DELETE FROM email_verify WHERE ev_user=?",'i',[$this->uid]);$sql->run("INSERT INTO email_verify (ev_user,ev_code,ev_expire) VALUES (?,?,?)",'iss',[$this->uid,$code,date('Y-m-d H:i:s',time()+600)]);$s=Mailer::send($em,'관리자 인증코드',"코드: {$code}\n(10분 유효)",$this->uid);$this->ok('인증코드 발송 완료',['verify_code_dev'=>$code,'mail_fail'=>!$s]);}

    private function productCreate(): void { $this->productWrite(false); } private function productUpdate(): void { $this->productWrite(true); }
