E users SET acc_nick=?,acc_intro=?,acc_phone=?,acc_address=?,acc_email=?,acc_pw=?,acc_onelogin=? WHERE acc_number=?",'ssssssii',[$nick,$intro,$phone,$addr,$email,$npw,$ol,$this->uid]);else $sql->run("UPDATE users SET acc_nick=?,acc_intro=?,acc_phone=?,acc_address=?,acc_email=?,acc_onelogin=? WHERE acc_number=?",'sssssii',[$nick,$intro,$phone,$addr,$email,$ol,$this->uid]);if($ns===1){$sql->run("UPDATE users SET acc_status=1 WHERE acc_number=?",'i',[$this->uid]);$code=mk_verify_code();$sql->run("INSERT INTO email_verify (ev_user,ev_code,ev_expire) VALUES (?,?,?)",'iss',[$this->uid,$code,date('Y-m-d H:i:s',time()+600)]);Mailer::send($email,'이메일 인증코드',"코드: {$code}\n(10분 유효)",$this->uid);}$ex=$sql->one("SELECT is_user FROM ip_security WHERE is_user=?",'i',[$this->uid]);if($ex)$sql->run("UPDATE ip_security SET is_check_ip=?,is_check_cc=?,is_allow_cc=? WHERE is_user=?",'iisi',[$cip,$ccc,$ca,$this->uid]);else $sql->run("INSERT INTO ip_security (is_user,is_check_ip,is_check_cc,is_allow_cc) VALUES (?,?,?,?)",'iiis',[$this->uid,$cip,$ccc,$ca]);if($chPw){unset($_SESSION['login']);if(session_status()===PHP_SESSION_ACTIVE){session_destroy();session_start();}rotate_csrf();$this->ok('저장 완료 (비밀번호 변경: 전체 로그아웃)',['redirect'=>'/?mode=authorize','notice'=>1]);return;}$this->ok('설정 저장 완료',['redirect'=>'/?mode=mypage','notice'=>1]);}
