    private function chatPoll(): self { global $sql, $system_v; $room=only_digits($_GET['room']??'',20);$last=only_digits($_GET['last']??'0',20);$isAdmin=(int)($system_v['login']['group']??0)===1;if((int)$room!==1&&(!$system_v['login']['valid']||(!$sql->one("SELECT 1 FROM chat_members WHERE cm_room=? AND cm_user=?",'ii',[(int)$room,$this->uid])&&!$isAdmin)))json_out(['error'=>1,'description'=>'권한 없음']);$rows=$sql->run("SELECT m.msg_id,m.msg_text,m.msg_kind,m.msg_ref,m.msg_user,COALESCE(NULLIF(u.acc_nick,''),u.acc_id) AS by_name FROM chat_messages m JOIN users u ON m.msg_user=u.acc_number WHERE m.msg_room=? AND m.msg_id>? ORDER BY m.msg_id LIMIT 100",'ii',[(int)$room,(int)$last]);$meN=$system_v['login']['valid']?(int)$system_v['login']['number']:-1;$out=[];foreach($rows as $r){$ext=strtolower(pathinfo($r['msg_ref'],PATHINFO_EXTENSION));$out[]=['msg_id'=>(int)$r['msg_id'],'by'=>$r['by_name'],'kind'=>(int)$r['msg_kind'],'text'=>$r['msg_text'],'ref'=>(int)$r['msg_kind']===1?('/uploads/'.e($r['msg_ref'])):$r['msg_ref'],'is_video'=>(int)$r['msg_kind']===1&&in_array($ext,$GLOBALS['ALLOW_VID_EXT'],true),'is_me'=>(int)$r['msg_user']===$meN,'time'=>$r['msg_time']];}json_out(['messages'=>$out,'__new_csrf'=>stable_csrf()]);return $this;}
