    private function chatPriv(): void { global $sql; $room=only_digits($_POST['room']??'',20);$kind=$_POST['kind']??'';$map=['phone'=>2,'account'=>3,'address'=>4];if($room===''||!isset($map[$kind])){$this->fail('Parameters error');return;}if((int)$room!==1&&!$sql->one("SELECT 1 FROM chat_members WHERE cm_room=? AND cm_user=?",'ii',[(int)$room,$this->uid])){$this->fail('No permission');return;}try{if((int)$sql->scalar("SELECT cr_blocked FROM chat_rooms WHERE room_id=?",'i',[(int)$room])===1){$this->fail('차단된 채팅방입니다');return;}}catch(\Throwable $e){}$pi=$sql->one("SELECT upi_real_name,upi_bank,upi_account,upi_phone,upi_address FROM user_payment_info WHERE upi_user=?",'i',[$this->uid]);if(!$pi){json_out(['error'=>1,'description'=>'Please register your payment info in My Page first.','require_payment_info'=>1,'redirect'=>'/?mode=mypage']);return;}$u=$sql->one("SELECT acc_phone,acc_address,acc_balance FROM users WHERE acc_number=?",'i',[$this->uid]);$val=$kind=='phone'?$pi['upi_phone']?:'not set':($kind=='account'?'Bank: '.$pi['upi_bank'].' '.$pi['upi_account'].' (Balance: '.number_format((int)$u['acc_balance']).'won)':($pi['upi_address']?:'not set')); $k=$map[$kind]; $sql->run("INSERT INTO chat_messages (msg_room,msg_user,msg_text,msg_kind,msg_ref,msg_time) VALUES (?,?,?,?,'',?)",'iisis',[(int)$room,$this->uid,$val,$k,now()]); $this->ok('Info sent');}

    private function reportCreate(): void { global $sql, $system_v; if(!empty($system_v['login']['report_ban'])){$this->fail('신고 권한이 제한되었습니다');return;}$t=only_digits($_POST['target']??'0',1);$ref=only_digits($_POST['ref']??'0',20);$reason=trim($_POST['reason']??'');if($t===''||$ref===''){$this->fail('대상 오류');return;}if(mb_strlen($reason)<5||mb_strlen($reason)>500){$this->fail('사유 5~500자');return;}$reason=htmlspecialchars($reason,ENT_QUOTES|ENT_HTML5,'UTF-8');$bw=bad_words_check($reason);if($bw[0]){$this->fail('비속어: '.e($bw[1]));return;}if((int)$t===1&&(int)$ref===$this->uid){$this->fail('본인 신고 불가');return;}if($sql->one("SELECT 1 FROM reports WHERE rpt_reporter=? AND rpt_target=? AND rpt_ref=?",'iii',[$this->uid,(int)$t,(int)$ref])){$this->fail('이미 신고함');return;}$sql->run("INSERT INTO reports (rpt_reporter,rpt_target,rpt_ref,rpt_reason,rpt_status,rpt_time) VALUES (?,?,?,?,0,?)",'iiiss',[$this->uid,(int)$t,(int)$ref,$reason,now()]);if((int)$t===0){$c=(int)$sql->scalar("SELECT COUNT(*) FROM reports WHERE rpt_target=0 AND rpt_ref=? AND rpt_status=0",'i',[(int)$ref]);$sql->run("UPDATE products SET prd_report_cnt=? WHERE prd_number=?",'ii',[$c,(int)$ref]);if($c>=5)$sql->run("UPDATE products SET prd_blind=1 WHERE prd_number=?",'i',[(int)$ref]);}else{$c=(int)$sql->scalar("SELECT COUNT(*) FROM reports WHERE rpt_target=1 AND rpt_ref=? AND rpt_status=0",'i',[(int)$ref]);if($c>=7)$sql->run("UPDATE users SET acc_status=2 WHERE acc_number=? AND acc_group<>1",'i',[(int)$ref]);}$this->ok('신고 접수 완료',['redirect'=>'/','notice'=>1]);}

    private function walletCharge(): void { global $sql; $amt=only_digits($_POST['amount']??'',12);if($amt===''||(int)$amt<=0||(int)$amt>100000000){$this->fail('금액 오류');return;}$info=$sql->one("SELECT upi_real_name,upi_account FROM user_payment_info WHERE upi_user=?",'i',[$this->uid]);if(!$info||$info['upi_real_name']===''||$info['upi_account']===''){$this->fail('결제정보 등록 필요',['redirect'=>'/?mode=mypage','need_payment'=>1]);return;}$sql->begin();$c=(int)$sql->scalar("SELECT acc_balance FROM users WHERE acc_number=?",'i',[$this->uid]);$a=$c+(int)$amt;$sql->run("UPDATE users SET acc_balance=? WHERE acc_number=?",'ii',[$a,$this->uid]);$sql->run("INSERT INTO wallet_ledger (led_user,led_kind,led_amount,led_counterparty,led_memo,led_balance_after,led_time) VALUES (?,0,?,NULL,'충전',?,?)",'iiis',[$this->uid,(int)$amt,$a,now()]);$sql->commit();$this->ok('충전 완료');}
    private function walletTransfer(): void { global $sql, $system_v; $to=only_digits($_POST['to']??'',20);$amt=only_digits($_POST['amount']??'',12);if($to===''||$amt===''||(int)$amt<=0){$this->fail('파라미터 오류');return;}if((int)$to===$this->uid){$this->fail('본인 송금 불가');return;}if((int)$amt>(int)$system_v['login']['balance']){$this->fail('잔액 부족');return;}$tu=$sql->one("SELECT acc_number FROM users WHERE acc_number=?",'i',[(int)$to]);if(!$tu){$this->fail('수신자 없음');return;}$info=$sql->one("SELECT upi_real_name,upi_account FROM user_payment_info WHERE upi_user=?",'i',[$this->uid]);if(!$info||$info['upi_real_name']===''||$info['upi_account']===''){$this->fail('결제정보 등록 필요',['redirect'=>'/?mode=mypage','need_payment'=>1]);return;}$sql->begin();$mc=(int)$sql->scalar("SELECT acc_balance FROM users WHERE acc_number=?",'i',[$this->uid]);$ma=$mc-(int)$amt;$sql->run("UPDATE users SET acc_balance=? WHERE acc_number=?",'ii',[$ma,$this->uid]);$sql->run("INSERT INTO wallet_ledger (led_user,led_kind,led_amount,led_counterparty,led_memo,led_balance_after,led_time) VALUES (?,1,?,?,?,?,?)",'iiisis',[$this->uid,(int)$amt,(int)$to,'송금',$ma,now()]);$tc=(int)$sql->scalar("SELECT acc_balance FROM users WHERE acc_number=?",'i',[(int)$to]);$ta=$tc+(int)$amt;$sql->run("UPDATE users SET acc_balance=? WHERE acc_number=?",'ii',[$ta,(int)$to]);$sql->run("INSERT INTO wallet_ledger (led_user,led_kind,led_amount,led_counterparty,led_memo,led_balance_after,led_time) VALUES (?,2,?,?,?,?,?)",'iiisis',[(int)$to,(int)$amt,$this->uid,'수취',$ta,now()]);$sql->commit();$this->ok('송금 완료');}
    private function walletBuy(): void { global $sql, $system_v; $pid=only_digits($_POST['prd']??'',20);if($pid===''){$this->fail('상품 오류');return;}$p=$sql->one("SELECT prd_number,prd_seller,prd_price,prd_sold,prd_blind FROM products WHERE prd_number=?",'i',[(int)$pid]);if(!$p){$this->fail('상품 없음');return;}if((int)$p['prd_sold']===1){$this->fail('이미 판매완료');return;}if((int)$p['prd_blind']===1){$this->fail('차단 상품');return;}if((int)$p['prd_seller']===$this->uid){$this->fail('본인 상품 구매 불가');return;}$info=$sql->one("SELECT upi_real_name,upi_account FROM user_payment_info WHERE upi_user=?",'i',[$this->uid]);if(!$info||$info['upi_real_name']===''||$info['upi_account']===''){$this->fail('결제정보 등록 필요',['redirect'=>'/?mode=mypage','need_payment'=>1]);return;}if((int)$p['prd_price']>(int)$system_v['login']['balance']){$this->fail('잔액 부족',['redirect'=>'/?mode=wallet']);return;}$sql->begin();$mc=(int)$sql->scalar("SELECT acc_balance FROM users WHERE acc_number=?",'i',[$this->uid]);$ma=$mc-(int)$p['prd_price'];$sl=(int)$p['prd_seller'];$sql->run("UPDATE users SET acc_balance=?,acc_buy_count=acc_buy_count+1,acc_trade_count=acc_trade_count+1 WHERE acc_number=?",'ii',[$ma,$this->uid]);$sql->run("INSERT INTO wallet_ledger (led_user,led_kind,led_amount,led_counterparty,led_memo,led_balance_after,led_time) VALUES (?,1,?,?,?,?,?)",'iiisis',[$this->uid,(int)$p['prd_price'],$sl,'구매 #'.$pid,$ma,now()]);$sc=(int)$sql->scalar("SELECT acc_balance FROM users WHERE acc_number=?",'i',[$sl]);$sa=$sc+(int)$p['prd_price'];$sql->run("UPDATE users SET acc_balance=?,acc_sell_count=acc_sell_count+1,acc_trade_count=acc_trade_count+1 WHERE acc_number=?",'ii',[$sa,$sl]);$sql->run("INSERT INTO wallet_ledger (led_user,led_kind,led_amount,led_counterparty,led_memo,led_balance_after,led_time) VALUES (?,2,?,?,?,?,?)",'iiisis',[$sl,(int)$p['prd_price'],$this->uid,'판매 #'.$pid,$sa,now()]);$sql->run("UPDATE products SET prd_sold=1 WHERE prd_number=?",'i',[(int)$pid]);$this->recomputeTrust($this->uid);$this->recomputeTrust($sl);$sql->commit();$this->ok('구매 완료',['redirect'=>'/?mode=view_post&view='.(int)$pid,'notice'=>1]);}
    private function transferConfirm(): void { global $sql; $to=only_digits($_POST['to']??'',20);if($to===''){$this->fail('사용자 번호 오류');return;}$u=$sql->one("SELECT acc_id FROM users WHERE acc_number=?",'i',[(int)$to]);if(!$u){$this->fail('사용자 없음');return;}$pay=$sql->one("SELECT upi_real_name,upi_phone,upi_bank,upi_account FROM user_payment_info WHERE upi_user=?",'i',[(int)$to]);$this->ok('사용자 확인 완료',['acc_id'=>$u['acc_id'],'name'=>$pay['upi_real_name']??'','phone'=>$pay['upi_phone']??'','bank'=>$pay['upi_bank']??'','account'=>$pay['upi_account']??'']);}
    private function recomputeTrust(int $uid): void { $sql=$GLOBALS['__db'];$u=$sql->one("SELECT acc_trade_count FROM users WHERE acc_number=?",'i',[$uid]);if(!$u)return;$rv=$sql->run("SELECT AVG(rv_score) AS a FROM reviews WHERE rv_target=?",'i',[$uid]);$av=isset($rv[0]['a'])?(float)$rv[0]['a']:50.0;$rp=(int)$sql->scalar("SELECT COUNT(*) FROM reports WHERE rpt_target=1 AND rpt_ref=?",'i',[$uid]);$tr=50+(int)$u['acc_trade_count']*1+($av/100)*30-$rp*10;$tr=max(0,min(100,$tr));$sql->run("UPDATE users SET acc_trust=ROUND(?,2) WHERE acc_number=?",'di',[$tr,$uid]);}

    private function masterAdminCreate(): void { global $sql; if((int)$sql->scalar("SELECT COUNT(*) FROM users WHERE acc_group=1")>0){$this->fail('이미 관리자가 존재합니다');return;}if(!$this->isLocalIp($this->ip)){$this->fail('로컬호스트만 가능');return;}$id=trim($_POST['form_id']??'');$pw=trim($_POST['form_pw']??'');$email=trim($_POST['form_email']??'');$tcode=trim($_POST['form_totp']??'');$csec=trim($_POST['totp_secret']??'');if($id===''||$id==='_check_'){$this->fail('TOTP 먼저 생성하세요',['totp_secret'=>Security::totp_secret()]);return;}if(!valid_accid($id)){$this->fail('ID 형식 오류');return;}if(!valid_password($pw)){$this->fail('비밀번호 형식 오류');return;}if(!valid_email($email)){$this->fail('이메일 형식 오류');return;}$sec=$csec!==''?$csec:'';if($sec===''){$this->fail('TOTP 먼저 생성하세요',['totp_secret'=>Security::totp_secret()]);return;}if(!preg_match('/^[0-9]{6}$/',$tcode)||!Security::totp_verify($sec,$tcode)){$this->fail('TOTP 코드 불일치',['totp_secret'=>$sec]);return;}if($sql->one("SELECT 1 FROM users WHERE acc_id=? OR acc_email=?",'ss',[$id,$email])){$this->fail('ID/이메일 중복');return;}$sql->run("INSERT INTO users (acc_id,acc_nick,acc_pw,acc_email,acc_group,acc_status,acc_onelogin,acc_totp_ok,acc_totp_secret,registertime) VALUES (?,?,?,?,1,0,1,1,?,?)",'ssssss',[$id,'Admin',hash_password($pw),$email,$sec,now()]);$this->ok('마스터 관리자 생성 완료',['redirect'=>'/?mode=authorize','notice'=>1]);}
    private function adminAutoPromote(): void { global $sql, $system_v; if(!$system_v['login']['valid']){$this->fail('로그인 필요');return;}if(!$this->isLocalIp($this->ip)){$this->fail('로컬호스트만 가능');return;}if((int)$sql->scalar("SELECT COUNT(*) FROM users WHERE acc_group=1 AND acc_status<>3")>0){$this->fail('관리자 이미 존재');return;}$sql->run("UPDATE users SET acc_group=1 WHERE acc_number=?",'i',[$this->uid]);$_SESSION['login']['group']=1;$this->ok('관리자 승격 완료',['redirect'=>'/?mode=mypage','notice'=>1]);}
