    private function uaSave(): void { global $sql; $list=trim($_POST['ua_list']??'');$mode=$_POST['ua_mode']??'or';if(!in_array($mode,['or','and'],true))$mode='or';$sql->run("DELETE FROM system_status WHERE ss_key IN ('ua_list','ua_mode')");$sql->run("INSERT INTO system_status (ss_key,ss_value,ss_time) VALUES ('ua_list',?,NOW())",'s',[$list]);$sql->run("INSERT INTO system_status (ss_key,ss_value,ss_time) VALUES ('ua_mode',?,NOW())",'s',[$mode]);$this->ok('UA 설정 저장 완료'); }

    private function logCleanup(): void { global $sql; $days=(int)($_POST['days']??30);if($days<1||$days>730)$days=30;$count=$sql->run("DELETE FROM request_log WHERE rl_time < DATE_SUB(NOW(), INTERVAL $days DAY)");$sql->run("DELETE FROM login_log WHERE lg_time < DATE_SUB(NOW(), INTERVAL $days DAY)");$sql->run("DELETE FROM visitor_log WHERE vl_time < DATE_SUB(NOW(), INTERVAL $days DAY)");$this->ok("{$days}일 이상 지난 로그 삭제 완료"); }

    private function pwReset(): void { global $sql; $id=trim($_POST['form_id']??'');$email=trim($_POST['form_email']??'');$totp=trim($_POST['form_totp']??'');if(!preg_match('/^[0-9a-zA-Z]{4,20}$/',$id)){$this->fail('ID 형식 오류');return;}$u=$sql->one("SELECT acc_number,acc_email,acc_totp_ok,acc_totp_secret,pw_reset_time FROM users WHERE acc_id=?",'s',[$id]);if(!$u){$this->fail('존재하지 않는 ID');return;}if($email===''||$u['acc_email']!==$email){$this->fail('이메일 불일치');return;}if((int)$u['acc_totp_ok']!==1){$this->fail('TOTP 미설정 계정');return;}$uid=(int)$u['acc_number'];if($totp===''){$this->fail('TOTP 필요',['step'=>1]);return;}if(!preg_match('/^[0-9]{6}$/',$totp)){$this->fail('TOTP 형식 오류');return;}try{$sql->run("ALTER TABLE users ADD COLUMN pw_reset_time DATETIME NULL DEFAULT NULL");}catch(\Throwable $e){}if($u['pw_reset_time']&&strtotime($u['pw_reset_time'])>time()){$r=strtotime($u['pw_reset_time'])-time();$this->fail(ceil($r/60).'분 후 재시도');return;}if(!Security::totp_verify($u['acc_totp_secret'],$totp)){$sql->run("UPDATE users SET pw_reset_time=DATE_ADD(NOW(), INTERVAL 1800 SECOND) WHERE acc_number=?",'i',[$uid]);$this->fail('TOTP 불일치 (30분 제한)');return;}$np=substr(str_shuffle('0123456789'),0,9);$hpw=hash_password($np);$sql->run("UPDATE users SET acc_pw=?,acc_onelogin=acc_onelogin+1,pw_reset_time=DATE_ADD(NOW(), INTERVAL 1800 SECOND) WHERE acc_number=?",'si',[$hpw,$uid]);$this->ok("비밀번호 초기화 완료. 새 비밀번호: $np",['new_pw'=>$np]); }

    private function pageLoad(): void {
        global $system_v, $sql, $L; $route=$_POST['route']??'board';$params=$_POST['params']??'';parse_str($params,$q);$_GET=array_merge($_GET,$q);$_GET['mode']=$route;$system_v['token']=stable_csrf();$system_v['view']=null;$system_v['page']=0;$system_v['desc_page']='';$system_v['header_name']=$L['nav_products']??'상품';$system_v['mode']='board';
        $P=['board'=>['page'=>'board','name'=>$L['nav_products']??'전체 상품','desc'=>'나무장터의 모든 중고 상품을 한눈에.'],'authorize'=>['page'=>'authorize','name'=>$L['nav_login']??'로그인','desc'=>'로그인 및 회원가입.'],'write_post'=>['page'=>'write_post','name'=>$L['nav_sell']??'상품 등록','desc'=>'중고 상품 등록.'],'view_post'=>['page'=>'view_post','name'=>$L['product_detail']??'상품 상세','desc'=>'상품 상세 정보.'],'mypage'=>['page'=>'mypage','name'=>$L['nav_mypage']??'마이페이지','desc'=>'내 계정 정보.'],'profile'=>['page'=>'profile','name'=>$L['profile_title']??'프로필','desc'=>'판매자 프로필.'],'report'=>['page'=>'report','name'=>$L['report_title']??'신고','desc'=>'부적절한 상품/사용자 신고.'],'dm'=>['page'=>'dm','name'=>$L['nav_chat']??'1:1 채팅','desc'=>'1:1 채팅.'],'review'=>['page'=>'review','name'=>'거래 평가','desc'=>'거래 상대방 평가.'],'chat'=>['page'=>'chat','name'=>'채팅 목록','desc'=>'대화 상대 목록.'],'wallet'=>['page'=>'wallet','name'=>$L['nav_wallet']??'내 지갑','desc'=>'가상 지갑.'],'admin'=>['page'=>'admin','name'=>$L['nav_admin']??'관리자','desc'=>'플랫폼 관리.'],'search'=>['page'=>'search','name'=>$L['search_title']??'검색','desc'=>'상품 검색.'],'terms'=>['page'=>'terms','name'=>$L['terms_title']??'이용약관','desc'=>'이용약관.'],'privacy'=>['page'=>'privacy','name'=>$L['privacy_title']??'개인정보처리방침','desc'=>'개인정보처리방침.'],'pw_reset'=>['page'=>'pw_reset','name'=>'비밀번호 초기화','desc'=>'TOTP로 비밀번호 초기화.']];
        if(isset($P[$route])){$system_v['mode']=$P[$route]['page'];$system_v['header_name']=$P[$route]['name'];$system_v['desc_page']=$P[$route]['desc'];}
        switch($system_v['mode']){case'authorize':if(isset($q['signup'])){$system_v['view']='signup';$system_v['header_name']=$L['nav_signup']??'회원가입';}elseif(isset($q['logout'])){$system_v['view']='logout';$system_v['header_name']=$L['nav_logout']??'로그아웃';}else{$system_v['view']='view';}break;case'write_post':if(isset($q['view'])&&preg_match('/^([0-9]){1,20}$/',$q['view'])){$system_v['view']=$q['view'];$system_v['header_name']=$L['product_edit']??'상품 수정';}break;case'view_post':if(isset($q['view'])&&preg_match('/^([0-9]){1,20}$/',$q['view']))$system_v['view']=$q['view'];break;case'profile':if(isset($q['view'])&&preg_match('/^([0-9]){1,20}$/',$q['view']))$system_v['view']=$q['view'];break;case'report':if(isset($q['target'])&&in_array($q['target'],['0','1'],true)&&isset($q['ref'])&&preg_match('/^([0-9]){1,20}$/',$q['ref']))$system_v['view']=$q['target'].'|'.$q['ref'];break;case'dm':if(isset($q['with'])&&preg_match('/^([0-9]){1,20}$/',$q['with']))$system_v['view']=$q['with'];elseif(isset($q['rid'])&&preg_match('/^([0-9]){1,20}$/',$q['rid']))$system_v['view']='0';break;}
        if(isset($q['page'])&&preg_match('/^([0-9]){1,20}$/',$q['page']))$system_v['page']=(int)$q['page'];
        $crumbs=[['name'=>$L['home']??'홈','href'=>'/']];if($system_v['mode']!=='board')$crumbs[]=['name'=>$system_v['header_name'],'href'=>'/?mode='.$route];
        ob_start();$pg=__DIR__.'/../../pages/'.$system_v['mode'].'.php';if(is_file($pg))include $pg;else echo'<div class="msg err">페이지를 찾을 수 없습니다</div>';$content=ob_get_clean();
        $bcHtml='';foreach($crumbs as $i=>$c){if($i>0)$bcHtml.='<span class="sep">/</span>';$bcHtml.='<a href="'.e($c['href']).'">'.e($c['name']).'</a>';}
        $lg=$system_v['login'];$topUser=$lg['valid']?($lg['nick']??$lg['id']):'';
        $sysN=(string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key=?","s",["notice"]);$sysU=(string)$sql->scalar("SELECT ss_value FROM system_status WHERE ss_key=?","s",["notice_urgent"]);$nBar='';if($sysU!=='')$nBar='<div class="urgent-bar" role="alert">'.e($sysU).'</div>';elseif($sysN!=='')$nBar='<div class="notice-bar" role="status">'.e($sysN).'</div>';
        $this->result=['success'=>1,'page_title'=>$system_v['header_name'],'meta_desc'=>$system_v['desc_page'],'breadcrumb'=>$bcHtml,'content_html'=>$content,'notice_bar'=>$nBar,'topbar_user'=>$topUser,'topbar_link_text'=>$lg['authorize_phrase']??'로그인','topbar_link_href'=>$lg['authorize_link']??'/?mode=authorize'];
    }
